$member=require_member();$commerceSettings=(array)app_store()->setting('commerce',[]);$order=app_store()->order((string)($_GET['order']??''));if(!$order||(string)$order['memberId']!==(string)$member['id']){http_response_code(404);$order=null;}
$pageTitle='Receipt';$activeNav='shop';require root_path('app/Views/public/partials/header.php');
