<div class="commerce-main"><section class="receipt-page"><?php if(!$order):?><h1>Receipt not found.</h1><?php else:?><header><div class="brand-lockup"><span class="brand-script">Nikki Wilder</span><span class="brand-sub">The Velvet Vixxen</span></div><div><span>Receipt</span><strong><?=e((string)$order['orderNumber'])?></strong></div></header><div class="receipt-meta"><div><span>Member</span><strong><?=e((string)$member['displayName'])?></strong><small><?=e((string)$member['email'])?></small></div><div><span>Order date</span><strong><?=e(date('F j, Y',strtotime((string)$order['createdAt'])))?></strong><small><?=e((string)$order['status'])?></small></div></div><table><thead><tr><th>Item</th><th>Quantity / option</th><th>Amount</th></tr></thead><tbody><?php foreach((array)$order['items'] as $item):?><tr><td><?=e((string)$item['title'])?></td><td><?=e((string)$item['quantity'])?> · <?=e((string)($item['metadata']['variantLabel']??ucfirst((string)($item['metadata']['purchaseMode']??$item['itemType']))))?></td><td><?=e(money((float)$item['lineTotal'],(string)$order['currency']))?></td></tr><?php endforeach;?></tbody></table><dl><div><dt>Subtotal</dt><dd><?=e(money((float)$order['subtotal'],(string)$order['currency']))?></dd></div><div><dt>Discount</dt><dd>−<?=e(money((float)$order['discountTotal'],(string)$order['currency']))?></dd></div><?php if(!empty($order['metadata']['requiresShipping'])):?><div><dt>Shipping</dt><dd><?=e(money((float)($order['metadata']['shippingTotal']??0),(string)$order['currency']))?></dd></div><?php endif;?><div><dt>Tax</dt><dd><?=e(money((float)$order['taxTotal'],(string)$order['currency']))?></dd></div><div class="total"><dt>Total</dt><dd><?=e(money((float)$order['grandTotal'],(string)$order['currency']))?></dd></div><?php if((float)$order['refundedTotal']>0):?><div><dt>Refunded</dt><dd><?=e(money((float)$order['refundedTotal'],(string)$order['currency']))?></dd></div><?php endif;?></dl><?php if(($order['metadata']['checkoutFlow']??'')==='merchandise'):?><p>Fulfillment: <?=e(ucfirst((string)($order['metadata']['shippingStatus']??'pending')))?><?php if(!empty($order['metadata']['trackingReference'])):?> · Tracking <?=e((string)$order['metadata']['trackingReference'])?><?php endif;?></p><?php endif;?><p class="receipt-footer-note"><?=e((string)($commerceSettings['receipt_footer']??'Thank you for supporting Nikki Wilder.'))?></p><div class="receipt-actions"><button class="button button--ghost" onclick="window.print()">Print Receipt</button><a class="button button--primary" href="<?=e(base_url('account/billing.php'))?>">Billing History</a></div><?php endif;?></section></div>
